  {
    "op": "add",
    "collection": "nodes",
    "id": "source-4",
    "value": {
      "type": "source",
      "text": "The steward chooses what the next work should be. After I have chosen, the orchestrator can insert the record for that already chosen work. Also, the orchestrator may ask me before stopping. Please capture that, without broadening it.",
      "status": "recorded",
      "meta": {
        "source_kind": "verbatim",
        "speaker": "user (Blake)",
        "date": "2026-09-15",
        "note": "First-person 'I'/'me' refers to the user as speaker; not resolved to a graph role."
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "orchestrator-inserts-chosen-record",
    "value": {
      "type": "claim",
      "text": "After the next work has been chosen (speaker: \"after I have chosen\"), the orchestrator can insert the record for that already chosen work.",
      "status": "proposed",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "modality": "permission (\"can\")",
        "condition": "Only after the choice has been made, and only for the work already chosen.",
        "scope_note": "Recording a chosen work item is distinct from choosing it; this claim does not grant the orchestrator any choice of next work.",
        "open_ambiguity": "Whether the speaker's 'I' is the steward role, the operator, or a distinct identity is unresolved."
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "orchestrator-may-ask-before-stopping",
    "value": {
      "type": "claim",
      "text": "The orchestrator may ask the speaker (\"me\") before stopping.",
      "status": "proposed",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "modality": "permission (\"may\"), not a requirement",
        "open_ambiguity": "Referent of 'me' (operator, steward, or the user as a distinct identity) and whether 'stopping' means ending a failed attempt specifically are unresolved."
      }
    }
  },
  {
    "op": "add",
